// Title: Hide rows generated by Aspose.Cells range smart markers when using AutoFilter in C#
// AI Prompts: Write C# code that creates a workbook, defines a named range containing smart markers, populates it from a List<T>, applies an AutoFilter to hide rows where a numeric column is below a threshold, and refreshes the filter with hideRows set to true. | Show how to set up AutoFitterOptions so that AutoFitRows skips rows hidden by an AutoFilter after processing range smart markers, then save the workbook as an XLSX file. | Demonstrate combining WorkbookDesigner, range smart markers, AutoFilter.Custom, and AutoFitRows to generate an Excel sheet where filtered rows are hidden and excluded from row‑height calculations.
// Common Searches: aspnet c# aspocells hide rows generated by smart markers after applying autofilter | how to hide filtered rows when using range smart markers in Aspose.Cells | c# Aspose.Cells auto filter rows with smart marker data and keep hidden rows out of autofit | Aspose.Cells hide rows with score less than 50 using smart markers and AutoFilter | range smart markers hide rows based on column value in Aspose.Cells C#
// Tags: range smart markers with AutoFilter | auto filter hide rows Aspose.Cells C# | AutoFitRows ignore hidden rows Aspose.Cells | WorkbookDesigner process list data C# | Excel XLSX output hide filtered rows

using System;
using System.Collections.Generic;
using Aspose.Cells;

namespace SmartMarkerRowHidingDemo
{
    // The example creates a workbook, defines a named range for range smart markers, processes a List<Person> via WorkbookDesigner, applies an AutoFilter to hide rows where the Score column is below 50, refreshes the filter with hideRows=true, configures AutoFitterOptions to ignore those hidden rows during AutoFitRows, and saves the result as SmartMarkerFilteredRows.xlsx.
    class Program
    {
        static void Main()
        {
            // 1. Create a new workbook (template) and set up smart markers
            Workbook workbook = new Workbook();
            Worksheet sheet = workbook.Worksheets[0];

            // Header row
            sheet.Cells["A1"].PutValue("Name");
            sheet.Cells["B1"].PutValue("Score");

            // Smart marker row (will be repeated for each data item)
            sheet.Cells["A2"].PutValue("&=Data.Name");
            sheet.Cells["B2"].PutValue("&=Data.Score");

            // Name the range that contains smart markers (required for range smart markers)
            sheet.Cells.CreateRange("A2:B2").Name = "_CellsSmartMarkers";

            // 2. Prepare sample data source
            var data = new List<Person>
            {
                new Person { Name = "Alice", Score = 85 },
                new Person { Name = "Bob",   Score = 45 },
                new Person { Name = "Carol", Score = 70 },
                new Person { Name = "Dave",  Score = 30 }
            };

            // 3. Process smart markers
            WorkbookDesigner designer = new WorkbookDesigner
            {
                Workbook = workbook,
                LineByLine = false // using range smart markers
            };
            designer.SetDataSource("Data", data);
            designer.Process();

            // 4. Apply an AutoFilter to hide rows where Score < 50
            // The data now occupies rows 2..(data.Count+1)
            int firstDataRow = 2; // 1‑based index for Excel rows
            int lastDataRow = firstDataRow + data.Count - 1;
            string filterRange = $"A{firstDataRow}:B{lastDataRow}";
            sheet.AutoFilter.Range = filterRange;
            sheet.AutoFilter.Custom(1, FilterOperatorType.LessThan, 50);
            // Refresh with hideRows = true so filtered rows become hidden
            sheet.AutoFilter.Refresh(true);

            // 5. Ensure that any further operations (e.g., AutoFit) ignore the hidden rows
            AutoFitterOptions fitOptions = new AutoFitterOptions
            {
                IgnoreHidden = true,
                AutoFitMergedCells = false,
                OnlyAuto = false
            };
            sheet.AutoFitRows(fitOptions);

            // 6. Save the result
            workbook.Save("SmartMarkerFilteredRows.xlsx", SaveFormat.Xlsx);
        }

        // Simple POCO for the data source
        public class Person
        {
            public string Name { get; set; }
            public int Score { get; set; }
        }
    }
}
